-- Isolated SQL-trigger authority evidence. This is not remote Auth/email proof.
begin;
create extension if not exists pgtap with schema extensions;select extensions.no_plan();
create temp table signup_prior_companies as select id,to_jsonb(c) as value from public.companies c;
insert into auth.users(id,email,raw_user_meta_data) values
 ('a7100000-0000-4000-8000-000000000001','signup-owner@local.invalid','{"company_name":"Synthetic Signup Contractor","full_name":"Signup Owner","operating_timezone":"America/Los_Angeles","role":"employee","company_id":"ffffffff-ffff-ffff-ffff-ffffffffffff"}'),
 ('a7100000-0000-4000-8000-000000000002','signup-other@local.invalid','{"company_name":"Other Synthetic Signup","full_name":"Other Owner","operating_timezone":"UTC"}');
select extensions.is((select role from public.profiles where id='a7100000-0000-4000-8000-000000000001'),'owner','legitimate signup gets the server-owned owner role regardless of metadata');
select extensions.ok((select company_id<>'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid from public.profiles where id='a7100000-0000-4000-8000-000000000001'),'metadata cannot select an existing or foreign tenant');
select extensions.ok(not exists(select 1 from signup_prior_companies p join public.companies c using(id) where p.value is distinct from to_jsonb(c)),'existing company values survive default removal and new signup');
select extensions.ok((select target_margin_percent is null and planned_productive_hours_annual is null and owner_compensation_target_annual is null and owner_planned_field_hours_annual is null and owner_field_rate is null from public.companies where id=(select company_id from public.profiles where id='a7100000-0000-4000-8000-000000000001')),'new financial inputs are unconfigured, not invented rates or zeros');
select extensions.is((select operating_timezone from public.companies where id=(select company_id from public.profiles where id='a7100000-0000-4000-8000-000000000001')),'America/Los_Angeles','new company retains the explicitly selected IANA zone');
select extensions.is((select count(*)::integer from public.projects where company_id=(select company_id from public.profiles where id='a7100000-0000-4000-8000-000000000001')),0,'signup creates no sample jobs');
insert into public.crew_members(id,company_id,name,role,worker_type,is_owner,active) select 'a7200000-0000-4000-8000-000000000001',company_id,'Invited Worker','Concrete finisher','employee',false,true from public.profiles where id='a7100000-0000-4000-8000-000000000001';
insert into public.crew_members(id,company_id,name,role,worker_type,is_owner,active) select 'a7200000-0000-4000-8000-000000000002',company_id,'Expired Worker','Concrete finisher','employee',false,true from public.profiles where id='a7100000-0000-4000-8000-000000000001';
select set_config('request.jwt.claim.sub','a7100000-0000-4000-8000-000000000001',true);set local role authenticated;
select extensions.lives_ok($$select public.carez_issue_employee_invite('a7200000-0000-4000-8000-000000000001',encode(sha256(convert_to(repeat('a',48),'UTF8')),'hex'))$$,'owner can issue a scoped employee invite');
select extensions.lives_ok($$select public.carez_issue_employee_invite('a7200000-0000-4000-8000-000000000002',encode(sha256(convert_to(repeat('b',48),'UTF8')),'hex'))$$,'another employee receives a separate invite');
select extensions.is((select count(*)::integer from public.employee_invites),2,'issuance preserves independent employee invitations');
select extensions.throws_like($$update public.employee_invites set accepted_at=now(),accepted_user_id=auth.uid()$$,'%permission denied%','an app client cannot mark a token consumed');
select extensions.throws_like($$update public.crew_members set profile_id=auth.uid() where id='a7200000-0000-4000-8000-000000000001'$$,'%verified invitation%','direct login binding cannot bypass verified acceptance');
reset role;set local role anon;
select extensions.ok(public.employee_invite_preview(repeat('a',48)) ?& array['employee_name','expires_at'],'anonymous preview exposes the supported name and expiry');
select extensions.is((select count(*)::integer from jsonb_object_keys(public.employee_invite_preview(repeat('a',48)))),2,'preview exposes no company, email, token fingerprint or profile authority');
select extensions.is(public.employee_invite_preview('malformed'),null::jsonb,'malformed preview is unavailable');
reset role;
insert into auth.users(id,email,raw_user_meta_data) values('a7100000-0000-4000-8000-000000000003','invited-worker@local.invalid',jsonb_build_object('employee_invite_token',repeat('a',48),'role','owner','company_id','ffffffff-ffff-ffff-ffff-ffffffffffff','full_name','Injected name'));
select extensions.is((select role from public.profiles where id='a7100000-0000-4000-8000-000000000003'),'employee','an accepted invite cannot promote itself to owner');
select extensions.is((select company_id from public.profiles where id='a7100000-0000-4000-8000-000000000003'),(select company_id from public.profiles where id='a7100000-0000-4000-8000-000000000001'),'invite determines company authority');
select extensions.is((select full_name from public.profiles where id='a7100000-0000-4000-8000-000000000003'),'Invited Worker','invite determines the associated employee name');
select extensions.is((select profile_id::text from public.crew_members where id='a7200000-0000-4000-8000-000000000001'),'a7100000-0000-4000-8000-000000000003','Crew receives the exact accepted login');
select extensions.ok((select accepted_at is not null and accepted_user_id='a7100000-0000-4000-8000-000000000003' from public.employee_invites where crew_member_id='a7200000-0000-4000-8000-000000000001'),'acceptance pair is persisted together');
select extensions.is(public.employee_invite_preview(repeat('a',48)),null::jsonb,'a consumed token is no longer available');
update public.employee_invites set expires_at=clock_timestamp()-interval '1 second' where crew_member_id='a7200000-0000-4000-8000-000000000002';
create function pg_temp.try_signup(p_metadata jsonb) returns void language sql as $$insert into auth.users(id,email,raw_user_meta_data) values('a7100000-0000-4000-8000-000000000099','invalid-signup@local.invalid',p_metadata);$$;
select extensions.throws_like($$select pg_temp.try_signup(jsonb_build_object('employee_invite_token',repeat('b',48)))$$,'%cannot be used%','expired invite never falls through to owner signup');
select extensions.throws_like($$select pg_temp.try_signup(jsonb_build_object('employee_invite_token',repeat('c',48)))$$,'%cannot be used%','unknown invite never creates a new company');
select extensions.throws_like($$select pg_temp.try_signup(jsonb_build_object('employee_invite_token',repeat('a',48)))$$,'%cannot be used%','consumed token cannot bind a second account');
select extensions.throws_like($$select pg_temp.try_signup('{"employee_invite_token":"","company_name":"Injection","full_name":"Fake","operating_timezone":"UTC"}')$$,'%cannot be used%','blank invite key rejects even when owner-signup fields are supplied');
select extensions.throws_like($$select pg_temp.try_signup('{"employee_invite_token":null}')$$,'%cannot be used%','null invite key is an invalid invite, not owner signup');
select extensions.throws_like($$select pg_temp.try_signup('{"company_name":"","full_name":"Name","operating_timezone":"UTC"}')$$,'%names are required%','company signup requires an actual company name');
select extensions.throws_like($$select pg_temp.try_signup('{"company_name":"Valid","full_name":"Name","operating_timezone":"Invented/Zone"}')$$,'%time zone%','company signup cannot invent a time-zone authority');
select extensions.is((select count(*)::integer from auth.users where id='a7100000-0000-4000-8000-000000000099'),0,'failed provisioning rolls back the auth-user insert');
select extensions.is((select count(*)::integer from public.companies),(select count(*)::integer+2 from signup_prior_companies),'failed invites create no spurious companies');
select set_config('request.jwt.claim.sub','a7100000-0000-4000-8000-000000000003',true);set local role authenticated;
select extensions.throws_like($$select public.carez_issue_employee_invite('a7200000-0000-4000-8000-000000000002',repeat('d',64))$$,'%Owner or office%','employee cannot issue invitations');
select extensions.throws_like($$update public.profiles set role='owner' where id=auth.uid()$$,'%permission denied%','profile role remains server controlled');
select extensions.throws_like($$insert into public.profiles(id,company_id,full_name,role) values(auth.uid(),'ffffffff-ffff-ffff-ffff-ffffffffffff','Injection','owner')$$,'%permission denied%','missing-profile recovery cannot be forged through a client insert');
reset role;
delete from auth.users where id='a7100000-0000-4000-8000-000000000003';
select extensions.is((select profile_id from public.crew_members where id='a7200000-0000-4000-8000-000000000001'),null::uuid,'account removal retains the existing Crew unlink behavior');
select extensions.ok((select accepted_at is not null and accepted_user_id='a7100000-0000-4000-8000-000000000003' from public.employee_invites where crew_member_id='a7200000-0000-4000-8000-000000000001'),'account removal preserves consumed-invite audit identity');
select extensions.is(public.employee_invite_preview(repeat('a',48)),null::jsonb,'removed account cannot make its consumed invitation reusable');
select * from extensions.finish();rollback;
